/**
 * Theme palette for editor preview.
 * Accepts a theme name string, or a live gauge payload with ``.theme``.
 * @param {string|{theme?: string}|null|undefined} nameOrData
 * @returns {object}
 */
function getTheme(nameOrData) {
  let name = 'Dark';
  if (typeof nameOrData === 'string') {
    name = nameOrData || 'Dark';
  } else if (nameOrData && typeof nameOrData === 'object') {
    name = nameOrData.theme || 'Dark';
  }
  return THEMES[name] || THEMES.Dark;
}

// ── Canvas helpers ─────────────────────────────────────────────────────────────

/**
 * Draw a rounded rectangle path. Polyfill for ctx.roundRect() which
 * is not available in older WebKits (Safari < 16.4).
 */
function roundRect(ctx, x, y, w, h, r) {
  if (typeof ctx.roundRect === 'function') {
    ctx.roundRect(x, y, w, h, r);
    return;
  }
  const clampedR = Math.min(r, w / 2, h / 2);
  ctx.moveTo(x + clampedR, y);
  ctx.arcTo(x + w, y,     x + w, y + h, clampedR);
  ctx.arcTo(x + w, y + h, x,     y + h, clampedR);
  ctx.arcTo(x,     y + h, x,     y,     clampedR);
  ctx.arcTo(x,     y,     x + w, y,     clampedR);
  ctx.closePath();
}

/**
 * Fill a rounded pill background with a thin border.
 * Similar look to matplotlib FancyBboxPatch in export styles — not identical geometry.
 */
function drawBackground(ctx, w, h, theme) {
  const pad = Math.max(2, Math.round(w * 0.02));
  const r   = Math.max(4, Math.round(Math.min(w, h) * 0.06));

  ctx.beginPath();
  roundRect(ctx, pad, pad, w - pad * 2, h - pad * 2, r);
  ctx.fillStyle = theme.bg;
  ctx.fill();

  ctx.beginPath();
  roundRect(ctx, pad, pad, w - pad * 2, h - pad * 2, r);
  ctx.strokeStyle = theme.bgEdge;
  ctx.lineWidth   = 1;
  ctx.stroke();
}

/**
 * Draw the thin vertical accent bar on the left edge.
 * Mirrors the ax.plot([0.035, 0.035], [0.08, 0.92]) pattern.
 */
function drawAccentBar(ctx, w, h, color) {
  const x    = Math.round(w * 0.035);
  const y1   = Math.round(h * 0.08);
  const y2   = Math.round(h * 0.92);
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth   = Math.max(1.5, w * 0.025);
  ctx.lineCap     = 'round';
  ctx.beginPath();
  ctx.moveTo(x, y1);
  ctx.lineTo(x, y2);
  ctx.stroke();
  ctx.restore();
}

/**
 * Scale font size proportionally to gauge dimensions
 * (same sqrt-area idea as ``overlay_utils.scale_factor`` for export).
 *
 * @param {number} baseSize   — reference font size at base dimensions
 * @param {number} w          — actual width
 * @param {number} h          — actual height
 * @param {number} baseW      — reference width  (default 120)
 * @param {number} baseH      — reference height (default 160)
 * @returns {number} pixel font size (integer, clamped to a minimum)
 */
function scaleFont(baseSize, w, h, baseW = 120, baseH = 160) {
  const sc = Math.sqrt((w / baseW) * (h / baseH));
  return Math.max(8, Math.round(baseSize * sc));
}

/**
 * Format a numeric gauge value for on-screen preview.
 * Keep rules compatible with ``styles/gauge_numeric.py`` so numbers read the same as export.
 *
 * @param {number} value
 * @param {string} channel
 * @returns {string}
 */
function fmtValue(value, channel) {
  if (channel === 'lap_time') {
    if (value == null || value < 0) return '—';
    const m = Math.floor(value / 60);
    const s = (value % 60).toFixed(3).padStart(6, '0');
    return value >= 60 ? `${m}:${s}` : value.toFixed(3);
  }
  if (channel === 'lean') return value.toFixed(1);
  if (channel === 'gforce_total' || channel === 'gforce_lat' || channel === 'gforce_lon' || channel === 'g_meter') {
    return value.toFixed(1);
  }
  if (channel === 'delta_time') {
    if (value == null) return '—';
    return (value >= 0 ? '+' : '') + value.toFixed(3);
  }
  const abs = Math.abs(value);
  if (abs >= 10000) return value.toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  if (abs >= 100)   return value.toFixed(0);
  if (abs >= 10)    return value.toFixed(1);
  return value.toFixed(2);
}

/**
 * Format a lap time as M:SS.mmm (for scoreboard / splits).
 */
function fmtTime(secs) {
  if (secs == null || secs < 0) return '—';
  const m = Math.floor(secs / 60);
  const s = (secs % 60).toFixed(3).padStart(6, '0');
  return `${m}:${s}`;
}

// Export as a namespace object (no ES module build step required)
const GaugeBase = { getTheme, roundRect, drawBackground, drawAccentBar, scaleFont, fmtValue, fmtTime, THEMES };

/* ----- numeric.js ----- */
/**
 * numeric.js — Numeric gauge: large centred value with label and unit.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_numeric.py`` / export.
 *
 * data keys: value, label, unit, channel
 * theme keys: bg, bgEdge, text, label (colour), unit (colour)
 */
const GaugeNumeric = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);
    const value   = data.value   ?? 0;
    const label   = (data.label  || '').toUpperCase();
    const unit    = data.unit    || '';
    const channel = data.channel || '';

    GaugeBase.drawBackground(ctx, w, h, theme);

    const sc = Math.sqrt((w / 120) * (h / 160));

    // Font sizes mirror gauge_numeric.py's scale_factor logic
    let fsLabel = Math.max(5,  Math.min(Math.round(11 * sc), Math.round(w * 0.13)));
    let fsValue = Math.max(10, Math.min(Math.round(34 * sc), Math.round(w * 0.38)));
    let fsUnit  = Math.max(5,  Math.min(Math.round(9  * sc), Math.round(w * 0.10)));

    // Format value string
    let txt;
    if (channel === 'lap_time') {
      txt     = GaugeBase.fmtValue(value, 'lap_time');
      // Tighter layout: large readout, label just above, almost no bottom gap
      fsValue = Math.max(11, Math.min(Math.round(28 * sc), Math.round(w * 0.32)));
      fsLabel = Math.max(6, Math.min(Math.round(10 * sc), Math.round(w * 0.11)));
    } else {
      txt = GaugeBase.fmtValue(value, channel);
    }

    ctx.textBaseline = 'middle';
    ctx.textAlign    = 'center';

    if (channel === 'lap_time') {
      ctx.fillStyle = theme.label;
      ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
      ctx.fillText(label, w * 0.5, h * 0.20);
      ctx.fillStyle  = theme.text;
      ctx.font       = `bold ${fsValue}px 'Segoe UI', sans-serif`;
      ctx.fillText(txt, w * 0.5, h * 0.56);
      if (unit && String(unit).trim()) {
        ctx.fillStyle = theme.unit;
        ctx.font      = `${fsUnit}px 'Segoe UI', sans-serif`;
        ctx.fillText(unit, w * 0.5, h * 0.82);
      }
      return;
    }

    // Label (top)
    ctx.fillStyle = theme.label;
    ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, w * 0.5, h * 0.22);

    // Value (centre)
    ctx.fillStyle  = theme.text;
    ctx.font       = `bold ${fsValue}px 'Segoe UI', sans-serif`;
    ctx.fillText(txt, w * 0.5, h * 0.50);

    // Unit (bottom)
    ctx.fillStyle = theme.unit;
    ctx.font      = `${fsUnit}px 'Segoe UI', sans-serif`;
    ctx.fillText(unit, w * 0.5, h * 0.78);
  }
};

/* ----- info.js ----- */
/**
 * info.js — Session info panel gauge.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_info.py`` / export.
 *
 * data keys:
 *   selected_fields  — list of field keys to show (e.g. ['track','datetime','weather','wind'])
 *   info_track, info_date, info_time, info_vehicle, info_session,
 *   info_weather, info_wind
 * theme keys: bg, bgEdge, text, label, fillPos
 */

const INFO_FIELDS_DEFAULT = ['track', 'datetime', 'vehicle', 'weather', 'wind'];

const GaugeInfo = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);
    GaugeBase.drawAccentBar(ctx, w, h, theme.fillPos);

    // Build value pairs for selected fields
    const allValues = {};

    const track  = data.info_track || '';
    allValues.track = ['TRACK', track || '—'];

    const dateS  = data.info_date || '';
    const timeS  = data.info_time || '';
    if (dateS && timeS)       allValues.datetime = ['DATE', `${dateS}  ${timeS}`];
    else if (dateS)           allValues.datetime = ['DATE', dateS];
    else                      allValues.datetime = ['DATE', '—'];

    const vehicle = data.info_vehicle || '';
    allValues.vehicle = ['VEHICLE', vehicle || '—'];

    const sessionT = data.info_session || '';
    allValues.session = ['SESSION', sessionT || '—'];

    const weather = data.info_weather || '';
    allValues.weather = ['WEATHER', weather || '—'];

    const wind = data.info_wind || '';
    allValues.wind = ['WIND', wind || '—'];

    const selected = (data.selected_fields && data.selected_fields.length > 0)
      ? data.selected_fields
      : INFO_FIELDS_DEFAULT;
    const align = data.text_align || 'left';

    const fields = selected
      .filter(k => allValues[k])
      .map(k => allValues[k]);

    if (fields.length === 0) fields.push(['INFO', '—']);

    const n       = fields.length;
    const padL    = w * 0.08;
    const yTop    = h * 0.94;
    const yBottom = h * 0.06;
    const rowH    = (yTop - yBottom) / Math.max(n, 1);

    // Font sizes derived from row height, matching gauge_info.py formula:
    // fs = max(4, int(h * row_h * ratio / 1.39))
    // row_h is the fraction 1/n, so row height in px = h/n
    const rowPx   = h / n;
    const fsLabel = Math.max(8,  Math.round(rowPx * 0.26));
    const fsValue = Math.max(10, Math.round(rowPx * 0.48));

    ctx.textBaseline = 'middle';
    let xText = padL;
    if (align === 'center') xText = w * 0.5;
    else if (align === 'right') xText = w * 0.92;
    ctx.textAlign = (align === 'center') ? 'center' : (align === 'right' ? 'right' : 'left');

    for (let i = 0; i < fields.length; i++) {
      const [lbl, val] = fields[i];
      const yc    = yTop - rowH * (i + 0.5);
      const yLbl  = yc + rowH * 0.20;
      const yVal  = yc - rowH * 0.14;

      ctx.fillStyle = theme.label;
      ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
      ctx.fillText(lbl, xText, yLbl);

      ctx.fillStyle  = theme.text;
      ctx.font       = `bold ${fsValue}px 'Segoe UI', sans-serif`;
      ctx.fillText(val, xText, yVal);
    }
  }
};

/* ----- scoreboard.js ----- */
/**
 * scoreboard.js — Lap scoreboard panel.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_lap_scoreboard.py`` / export.
 *
 * data keys: lap_num, total_laps, lap_elapsed, best_so_far (number | null)
 * theme keys: bg, bgEdge, text, label, fillPos, fillLo, fillHi
 */
const GaugeScoreboard = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);
    GaugeBase.drawAccentBar(ctx, w, h, theme.fillPos);

    const lapNum    = Math.max(0, Math.round(data.lap_num    ?? 1));
    const totalLaps = Math.max(1, Math.round(data.total_laps ?? 1));
    const elapsed   = data.lap_elapsed ?? 0;
    const bestMode  = data.best_mode === 'session' ? 'session' : 'so_far';
    const best      = (bestMode === 'session') ? data.session_best : data.best_so_far;

    // Delta — show only live reference-lap delta when available.
    let deltaTxt, deltaCol;
    const liveDelta = data.delta_time;
    if (liveDelta != null) {
      deltaTxt = liveDelta >= 0 ? `+${Math.abs(liveDelta).toFixed(3)}` : `-${Math.abs(liveDelta).toFixed(3)}`;
      deltaCol = liveDelta < 0 ? theme.fillLo : theme.fillHi;
    } else {
      deltaTxt = '—';
      deltaCol = theme.label;
    }

    const isOutlap = lapNum === 0;
    const lapLabel = isOutlap ? 'OUT LAP' : 'LAP';
    const lapVal   = isOutlap ? '—' : `${lapNum} / ${totalLaps}`;

    const allRows = {
      lap:     [lapLabel, lapVal,                                    theme.text],
      best:    ['BEST',   best != null ? GaugeBase.fmtTime(best) : '—', theme.label],
      current: ['CURRENT', GaugeBase.fmtTime(elapsed),              theme.text],
      delta:   ['DELTA',   deltaTxt,                                 deltaCol],
    };
    const sel  = data.selected_fields || ['lap','best','current','delta'];
    const rows = sel.filter(k => allRows[k]).map(k => allRows[k]);
    if (rows.length === 0) rows.push(['—', '—', theme.label]);
    const align = data.text_align || 'split'; // split | left | center | right

    const n       = rows.length;
    const yTop    = h * 0.94;
    const yBottom = h * 0.06;
    const rowH    = (yTop - yBottom) / n;

    // Font sizes matching gauge_lap_scoreboard.py formula:
    // fs_label = max(5, int(h * row_h * 0.28 / 1.39))
    // row_h = 1/n (fraction), so row height in px = h/n
    const rowPx   = h / n;
    const fsLabel = Math.max(8,  Math.round(rowPx * 0.28));
    const fsValue = Math.max(10, Math.round(rowPx * 0.52));

    const padL = w * 0.08;

    // Thin horizontal dividers between rows
    ctx.strokeStyle = theme.bgEdge;
    ctx.lineWidth   = 0.5;
    for (let i = 1; i < n; i++) {
      const yDiv = yTop - rowH * i;
      ctx.beginPath();
      ctx.moveTo(w * 0.06, yDiv);
      ctx.lineTo(w * 0.97, yDiv);
      ctx.stroke();
    }

    ctx.textBaseline = 'middle';

    for (let i = 0; i < rows.length; i++) {
      const [lbl, val, col] = rows[i];
      const yc   = yTop - rowH * (i + 0.5);
      const yLbl = yc + rowH * 0.20;
      const yVal = yc - rowH * 0.12;

      // Label
      const xLbl = align === 'center' ? (w * 0.5) : (align === 'right' ? (w * 0.97) : padL);
      ctx.textAlign = align === 'center' ? 'center' : (align === 'right' ? 'right' : 'left');
      ctx.fillStyle = theme.label;
      ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
      ctx.fillText(lbl, xLbl, yLbl);

      // Value
      const xVal = align === 'split' ? (w * 0.97) : (align === 'center' ? (w * 0.5) : (align === 'right' ? (w * 0.97) : padL));
      ctx.textAlign  = align === 'split' ? 'right' : (align === 'center' ? 'center' : (align === 'right' ? 'right' : 'left'));
      ctx.fillStyle  = col;
      ctx.font       = `bold ${fsValue}px 'Consolas', monospace`;
      ctx.fillText(val, xVal, yVal);
    }
  }
};

/* ----- bar.js ----- */
/**
 * bar.js — Horizontal fill bar gauge with sparkline.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_bar.py`` / export.
 *
 * data keys: value, history_vals, label, unit, min_val, max_val, symmetric
 * theme keys: bg, bgEdge, track, fillPos, fillNeg, fillLo, fillHi, label, trace
 */
const GaugeBar = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    const value     = data.value      ?? 0;
    const hist      = data.history_vals || [value];
    const label     = (data.label     || '').toUpperCase();
    const unit      = data.unit       || '';
    const mn        = data.min_val    ?? 0;
    const mx        = data.max_val    ?? 100;
    const symmetric = data.symmetric  ?? false;

    const sc = Math.sqrt((w / 180) * (h / 120));

    const fsLabel = Math.max(8, Math.min(Math.round(10 * sc), Math.round(w * 0.08)));
    const fsVal   = Math.max(9, Math.min(Math.round(13 * sc), Math.round(w * 0.10)));

    const PAD   = w * 0.08;
    const BAR_L = PAD;
    const BAR_R = w - PAD;
    const barW  = BAR_R - BAR_L;
    const BAR_Y = h * 0.38;   // top of bar
    const BAR_H = h * 0.22;

    // Label (top zone)
    ctx.textBaseline = 'middle';
    ctx.textAlign    = 'center';
    ctx.fillStyle    = theme.label;
    ctx.font         = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, w * 0.5, h * 0.89);

    // Track background for bar
    ctx.fillStyle = theme.track;
    ctx.beginPath();
    GaugeBase.roundRect(ctx, BAR_L, BAR_Y, barW, BAR_H, 2);
    ctx.fill();

    const rng = mx !== mn ? mx - mn : 1;
    let fillCol;

    if (symmetric) {
      const midX  = BAR_L + barW * (-mn / rng);
      const frac  = (value - mn) / rng;
      const fillX = BAR_L + barW * Math.max(0, Math.min(1, frac));

      if (value >= 0) {
        fillCol = theme.fillPos;
        ctx.fillStyle = fillCol;
        ctx.globalAlpha = 0.9;
        const fw = fillX - midX;
        if (fw > 0) {
          ctx.fillRect(midX, BAR_Y, fw, BAR_H);
        }
      } else {
        fillCol = theme.fillNeg;
        ctx.fillStyle = fillCol;
        ctx.globalAlpha = 0.9;
        const fw = midX - fillX;
        if (fw > 0) {
          ctx.fillRect(fillX, BAR_Y, fw, BAR_H);
        }
      }
      ctx.globalAlpha = 1;

      // Centre tick
      ctx.strokeStyle = '#3a4a5a';
      ctx.lineWidth   = 1;
      ctx.beginPath();
      ctx.moveTo(midX, BAR_Y - 2);
      ctx.lineTo(midX, BAR_Y + BAR_H + 2);
      ctx.stroke();
    } else {
      const frac  = Math.max(0, Math.min(1, (value - mn) / rng));
      fillCol = frac < 0.75 ? theme.fillLo : theme.fillHi;
      ctx.fillStyle   = fillCol;
      ctx.globalAlpha = 0.9;
      ctx.fillRect(BAR_L, BAR_Y, barW * frac, BAR_H);
      ctx.globalAlpha = 1;
    }

    // Value text (between bar and sparkline)
    const valStr = unit ? `${value.toFixed(1)} ${unit}` : value.toFixed(1);
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle    = fillCol || theme.fillLo;
    ctx.font         = `bold ${fsVal}px 'Segoe UI', sans-serif`;
    ctx.fillText(valStr, w * 0.5, h * 0.25);

    // Sparkline (bottom zone: 5%–27% of height)
    const n = Math.min(50, hist.length);
    if (n >= 2) {
      const vals = hist.slice(-n);
      const spYT = h * 0.05;
      const spYB = h * 0.27;
      const spH  = spYB - spYT;

      ctx.strokeStyle = theme.trace;
      ctx.lineWidth   = Math.max(0.6, 0.8 * sc);
      ctx.beginPath();
      for (let i = 0; i < vals.length; i++) {
        const x = BAR_L + barW * (i / (vals.length - 1));
        const y = spYT + spH * (1 - Math.max(0, Math.min(1, (vals[i] - mn) / rng)));
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
  }
};

/* ----- line.js ----- */
/**
 * line.js — Area chart of channel history with value readout.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_line.py`` / export.
 *
 * data keys: value, history_vals, label, unit, min_val, max_val, symmetric, channel
 * theme keys: bg, bgEdge, track, fillPos, fillNeg, fillLo, fillHi, label, unit
 */
const GaugeLine = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    const value     = data.value      ?? 0;
    const hist      = data.history_vals || [value];
    const label     = (data.label     || '').toUpperCase();
    const unit      = data.unit       || '';
    const mn        = data.min_val    ?? 0;
    const mx        = data.max_val    ?? 100;
    const symmetric = data.symmetric  ?? false;
    const channel   = data.channel    || '';

    const sc = Math.sqrt((w / 220) * (h / 100));

    const fsLabel = Math.max(8,  Math.min(Math.round(9  * sc), Math.round(w * 0.07)));
    const fsVal   = Math.max(9,  Math.min(Math.round(14 * sc), Math.round(w * 0.11)));
    const fsUnit  = Math.max(7,  Math.min(Math.round(7  * sc), Math.round(w * 0.06)));

    // Chart area: left 68% of width, middle 62% of height
    const cX = w * 0.04;
    const cY = h * 0.20;
    const cW = w * 0.68;
    const cH = h * 0.62;

    const rng = mx !== mn ? mx - mn : 1;
    const pad = rng * 0.08;
    const yMin = mn - pad;
    const yMax = mx + pad;
    const yRng = yMax - yMin;

    // Line colour
    let lineCol;
    if (symmetric) {
      lineCol = value >= 0 ? theme.fillPos : theme.fillNeg;
    } else {
      const frac = Math.max(0, Math.min(1, (value - mn) / rng));
      lineCol = frac > 0.80 ? theme.fillHi : theme.fillLo;
    }

    // Clip to chart area
    ctx.save();
    ctx.beginPath();
    ctx.rect(cX, cY, cW, cH);
    ctx.clip();

    const n    = Math.min(120, hist.length);
    const vals = hist.slice(-n);

    function toScreenX(i) { return cX + cW * (i / Math.max(1, vals.length - 1)); }
    function toScreenY(v) {
      return cY + cH * (1 - Math.max(0, Math.min(1, (v - yMin) / yRng)));
    }

    // Zero line for symmetric channels
    if (symmetric) {
      const y0 = toScreenY(0);
      ctx.strokeStyle = theme.track;
      ctx.lineWidth   = 0.8;
      ctx.beginPath();
      ctx.moveTo(cX, y0);
      ctx.lineTo(cX + cW, y0);
      ctx.stroke();
    }

    if (vals.length >= 2) {
      // Fill under the trace
      const baseline = toScreenY(symmetric ? 0 : mn);

      ctx.beginPath();
      ctx.moveTo(toScreenX(0), baseline);
      for (let i = 0; i < vals.length; i++) {
        ctx.lineTo(toScreenX(i), toScreenY(vals[i]));
      }
      ctx.lineTo(toScreenX(vals.length - 1), baseline);
      ctx.closePath();
      ctx.fillStyle   = lineCol;
      ctx.globalAlpha = 0.18;
      ctx.fill();
      ctx.globalAlpha = 1;

      // Trace line
      ctx.beginPath();
      for (let i = 0; i < vals.length; i++) {
        const x = toScreenX(i);
        const y = toScreenY(vals[i]);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = lineCol;
      ctx.lineWidth   = Math.max(1, 1.4 * sc);
      ctx.lineCap     = 'round';
      ctx.stroke();
    }

    ctx.restore();

    // Label (top-left)
    ctx.textBaseline = 'top';
    ctx.textAlign    = 'left';
    ctx.fillStyle    = theme.label;
    ctx.font         = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, w * 0.04, h * 0.05);

    // Value readout (right panel, upper half)
    const valStr = GaugeBase.fmtValue(value, channel);
    ctx.textBaseline = 'middle';
    ctx.textAlign    = 'right';
    ctx.fillStyle    = lineCol;
    ctx.font         = `bold ${fsVal}px 'Segoe UI', sans-serif`;
    ctx.fillText(valStr, w * 0.97, h * 0.44);

    if (unit) {
      ctx.fillStyle = theme.unit;
      ctx.font      = `${fsUnit}px 'Segoe UI', sans-serif`;
      ctx.fillText(unit, w * 0.97, h * 0.72);
    }
  }
};

/* ----- delta.js ----- */
/**
 * delta.js — Delta time gauge (current vs reference lap).
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_delta.py`` / export.
 *
 * data keys: value (delta_seconds), history_vals, label
 * theme keys: bg, bgEdge, label
 */
const GaugeDelta = {
  _NEUTRAL_BAND: 0.10,

  _colour(delta) {
    if (Math.abs(delta) <= this._NEUTRAL_BAND) return '#e8e8e8';
    return delta < 0 ? '#22dd66' : '#ff4444';
  },

  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    const hasValue = data.value != null && Number.isFinite(data.value);
    const value   = hasValue ? Number(data.value) : 0;
    const history = data.history_vals || [];
    const label   = (data.label || 'Delta').toUpperCase();

    const sc = Math.sqrt((w / 120) * (h / 160));

    const fsLabel = Math.max(8, Math.min(Math.round(10 * sc), Math.round(w * 0.12)));
    const fsValue = Math.max(12, Math.min(Math.round(28 * sc), Math.round(w * 0.16)));

    const colour = hasValue ? this._colour(value) : theme.label;

    // Sign + value text
    const txt = hasValue ? ((value >= 0 ? '+' : '\u2212') + Math.abs(value).toFixed(3)) : '—';

    ctx.textBaseline = 'middle';
    ctx.textAlign    = 'center';

    // Label
    ctx.fillStyle = theme.label;
    ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, w * 0.5, h * 0.20);

    // Value
    ctx.fillStyle  = colour;
    ctx.font       = `bold ${fsValue}px 'Segoe UI', sans-serif`;
    ctx.fillText(txt, w * 0.5, h * 0.54);

    // Sparkline (bottom 18% of height)
    const n = Math.min(150, history.length);
    if (n >= 2) {
      const vals   = history.slice(-n);
      const spX    = w * 0.08;
      const spY    = h * 0.75;
      const spW    = w * 0.84;
      const spH    = h * 0.18;

      // Determine y range from data
      let lo = Math.min(...vals);
      let hi = Math.max(...vals);
      if (lo === hi) { lo -= 1; hi += 1; }
      const rng = hi - lo;

      function toX(i) { return spX + spW * (i / (vals.length - 1)); }
      function toY(v) { return spY + spH * (1 - Math.max(0, Math.min(1, (v - lo) / rng))); }

      // Zero line
      const y0 = toY(0);
      ctx.strokeStyle = 'rgba(255,255,255,0.25)';
      ctx.lineWidth   = 0.5;
      ctx.beginPath();
      ctx.moveTo(spX, y0);
      ctx.lineTo(spX + spW, y0);
      ctx.stroke();

      // Fill positive (slower) = red
      ctx.beginPath();
      ctx.moveTo(toX(0), Math.min(toY(vals[0]), y0));
      for (let i = 0; i < vals.length; i++) {
        ctx.lineTo(toX(i), toY(vals[i]));
      }
      ctx.lineTo(toX(vals.length - 1), y0);
      ctx.closePath();
      ctx.fillStyle   = '#ff4444';
      ctx.globalAlpha = 0.35;
      ctx.fill();
      ctx.globalAlpha = 1;

      // Fill negative (faster) = green
      ctx.beginPath();
      ctx.moveTo(toX(0), Math.max(toY(vals[0]), y0));
      for (let i = 0; i < vals.length; i++) {
        ctx.lineTo(toX(i), toY(vals[i]));
      }
      ctx.lineTo(toX(vals.length - 1), y0);
      ctx.closePath();
      ctx.fillStyle   = '#22dd66';
      ctx.globalAlpha = 0.35;
      ctx.fill();
      ctx.globalAlpha = 1;

      // Trend line
      ctx.strokeStyle = colour;
      ctx.lineWidth   = 0.8;
      ctx.globalAlpha = 0.9;
      ctx.beginPath();
      for (let i = 0; i < vals.length; i++) {
        const x = toX(i);
        const y = toY(vals[i]);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
  }
};

/* ----- delta_bar.js ----- */
/**
 * delta_bar.js — iRacing/RaceChrono-like delta bar.
 *
 * Centered zero line:
 * - negative (faster) fills to left in green
 * - positive (slower) fills to right in red
 */
const GaugeDeltaBar = {
  _NEUTRAL_BAND: 0.10,

  /** Map seconds → [0..1] bar length (half-width scale). Similar to iRacing-style HUDs:
   *  - smaller full-scale (default ±1.0s) so small deltas are visible
   *  - power curve (exponent < 1) boosts small values without instantly maxing out
   */
  _barMagnitude(delta, fullScale = 1.0, exponent = 0.45) {
    const fs = Math.max(0.05, Number(fullScale) || 1.0);
    const u = Math.min(1, Math.abs(delta) / fs);
    return Math.pow(u, Math.max(0.15, Math.min(1, Number(exponent) || 0.45)));
  },

  _colour(delta) {
    if (Math.abs(delta) <= this._NEUTRAL_BAND) return '#e8e8e8';
    return delta < 0 ? '#22dd66' : '#ff4444';
  },

  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);
    GaugeBase.drawBackground(ctx, w, h, theme);

    const hasValue = data.value != null && Number.isFinite(data.value);
    const value = hasValue ? Number(data.value) : 0;
    const label = (data.label || 'Delta').toUpperCase();
    const fullScale = Number(data.delta_bar_full_scale ?? 1.0);
    const curveExp = Number(data.delta_bar_curve ?? 0.45);

    const sc = Math.sqrt((w / 180) * (h / 120));
    const fsLabel = Math.max(8, Math.min(Math.round(10 * sc), Math.round(w * 0.08)));
    const fsVal = Math.max(9, Math.min(Math.round(15 * sc), Math.round(w * 0.12)));

    const pad = w * 0.08;
    const x0 = pad;
    const x1 = w - pad;
    const bw = x1 - x0;
    const by = h * 0.42;
    const bh = h * 0.20;
    const cx = (x0 + x1) * 0.5;

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = theme.label;
    ctx.font = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, w * 0.5, h * 0.84);

    ctx.fillStyle = theme.track;
    ctx.beginPath();
    GaugeBase.roundRect(ctx, x0, by, bw, bh, 2);
    ctx.fill();

    const mag = hasValue ? this._barMagnitude(value, fullScale, curveExp) : 0;
    const sign = value > 0 ? 1 : (value < 0 ? -1 : 0);
    const frac = sign * mag;
    if (frac > 0) {
      ctx.fillStyle = '#ff4444';
      ctx.globalAlpha = 0.9;
      ctx.fillRect(cx, by, (bw * 0.5) * frac, bh);
      ctx.globalAlpha = 1;
    } else if (frac < 0) {
      ctx.fillStyle = '#22dd66';
      ctx.globalAlpha = 0.9;
      ctx.fillRect(cx + (bw * 0.5) * frac, by, (bw * 0.5) * (-frac), bh);
      ctx.globalAlpha = 1;
    }

    ctx.strokeStyle = '#3a4a5a';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(cx, by - 2);
    ctx.lineTo(cx, by + bh + 2);
    ctx.stroke();

    const text = hasValue ? ((value >= 0 ? '+' : '\u2212') + Math.abs(value).toFixed(3)) : '—';
    ctx.fillStyle = hasValue ? this._colour(value) : theme.label;
    ctx.font = `bold ${fsVal}px 'Segoe UI', sans-serif`;
    ctx.fillText(text, w * 0.5, h * 0.25);
  }
};

/* ----- compare.js ----- */
/**
 * compare.js — Dual-trace line chart: current lap vs reference lap.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_compare.py`` / export.
 *
 * data keys: value, history_vals, ref_history_vals, label, unit,
 *            min_val, max_val, symmetric, channel
 * theme keys: bg, bgEdge, fillPos, fillNeg, fillLo, fillHi, label, unit, track
 */
const GaugeCompare = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    const value     = data.value          ?? 0;
    const hist      = data.history_vals   || [value];
    const refHist   = data.ref_history_vals || [];
    const label     = (data.label         || '').toUpperCase();
    const unit      = data.unit           || '';
    const mn        = data.min_val        ?? 0;
    const mx        = data.max_val        ?? 100;
    const symmetric = data.symmetric      ?? false;
    const channel   = data.channel        || '';

    const sc = Math.sqrt((w / 220) * (h / 100));

    const fsLabel = Math.max(8,  Math.min(Math.round(9  * sc), Math.round(w * 0.07)));
    const fsVal   = Math.max(9,  Math.min(Math.round(13 * sc), Math.round(w * 0.10)));
    const fsUnit  = Math.max(7,  Math.min(Math.round(7  * sc), Math.round(w * 0.06)));
    const fsLeg   = Math.max(7,  Math.min(Math.round(6  * sc), Math.round(w * 0.055)));

    const rng = mx !== mn ? mx - mn : 1;

    let lineCol;
    if (symmetric) {
      lineCol = value >= 0 ? theme.fillPos : theme.fillNeg;
    } else {
      const frac = Math.max(0, Math.min(1, (value - mn) / rng));
      lineCol = frac > 0.80 ? theme.fillHi : theme.fillLo;
    }

    const refCol = '#999999';

    // Chart area
    const cX = w * 0.04;
    const cY = h * 0.20;
    const cW = w * 0.70;
    const cH = h * 0.62;

    const pad  = rng * 0.10;
    const yMin = mn - pad;
    const yMax = mx + pad;
    const yRng = yMax - yMin;

    ctx.save();
    ctx.beginPath();
    ctx.rect(cX, cY, cW, cH);
    ctx.clip();

    const n       = Math.min(120, hist.length);
    const curVals = hist.slice(-n);

    function toX(i) { return cX + cW * (i / Math.max(1, curVals.length - 1)); }
    function toY(v) { return cY + cH * (1 - Math.max(0, Math.min(1, (v - yMin) / yRng))); }

    if (symmetric) {
      const y0 = toY(0);
      ctx.strokeStyle = theme.track;
      ctx.lineWidth   = 0.6;
      ctx.beginPath();
      ctx.moveTo(cX, y0);
      ctx.lineTo(cX + cW, y0);
      ctx.stroke();
    }

    // Reference trace (dashed grey)
    const hasRef = refHist.length >= 2;
    if (hasRef) {
      let refVals = refHist.slice(-n);
      // Align lengths
      while (refVals.length < curVals.length) refVals.unshift(refVals[0]);
      if (refVals.length > curVals.length) refVals = refVals.slice(-curVals.length);

      ctx.strokeStyle = refCol;
      ctx.lineWidth   = Math.max(0.8, sc);
      ctx.globalAlpha = 0.70;
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      for (let i = 0; i < refVals.length; i++) {
        const x = toX(i);
        const y = toY(refVals[i]);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 1;
    }

    // Current trace + fill
    if (curVals.length >= 2) {
      const baseline = toY(symmetric ? 0 : mn);

      ctx.beginPath();
      ctx.moveTo(toX(0), baseline);
      for (let i = 0; i < curVals.length; i++) {
        ctx.lineTo(toX(i), toY(curVals[i]));
      }
      ctx.lineTo(toX(curVals.length - 1), baseline);
      ctx.closePath();
      ctx.fillStyle   = lineCol;
      ctx.globalAlpha = 0.12;
      ctx.fill();
      ctx.globalAlpha = 1;

      ctx.beginPath();
      for (let i = 0; i < curVals.length; i++) {
        const x = toX(i);
        const y = toY(curVals[i]);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = lineCol;
      ctx.lineWidth   = Math.max(1, 1.4 * sc);
      ctx.lineCap     = 'round';
      ctx.stroke();
    }

    ctx.restore();

    // Label (top-left)
    ctx.textBaseline = 'top';
    ctx.textAlign    = 'left';
    ctx.fillStyle    = theme.label;
    ctx.font         = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, w * 0.04, h * 0.05);

    // Value (right panel, top)
    const valStr = GaugeBase.fmtValue(value, channel);
    ctx.textBaseline = 'top';
    ctx.textAlign    = 'right';
    ctx.fillStyle    = lineCol;
    ctx.font         = `bold ${fsVal}px 'Segoe UI', sans-serif`;
    ctx.fillText(valStr, w * 0.97, h * 0.08);

    if (unit) {
      ctx.fillStyle = theme.unit;
      ctx.font      = `${fsUnit}px 'Segoe UI', sans-serif`;
      ctx.fillText(unit, w * 0.97, h * 0.30);
    }

    // Legend
    if (hasRef) {
      ctx.textBaseline = 'middle';
      ctx.fillStyle    = lineCol;
      ctx.font         = `${fsLeg}px 'Segoe UI', sans-serif`;
      ctx.fillText('\u2014 NOW', w * 0.97, h * 0.72);

      ctx.fillStyle = refCol;
      ctx.fillText('-- REF', w * 0.97, h * 0.87);
    }
  }
};

/* ----- multiline.js ----- */
/**
 * multiline.js — Multi-channel overlaid line chart with legend (editor preview).
 *
 * ``data.multi_channels`` matches export; ``data.palette`` is optional and should
 * list the same hex sequence as ``gauge_channels.GAUGE_COLOURS`` when provided by
 * the editor (``get_editor_catalog``).
 *
 * data keys: multi_channels (…), optional palette (string[])
 */

const _DEFAULT_LINE_PALETTE = [
  '#00d4ff', '#ff6b35', '#a8ff3e', '#ff3ea8',
  '#ffd700', '#3ea8ff', '#ff3e3e', '#3effd7',
  '#c084fc', '#fb923c',
];

function _linePalette(data) {
  const p = data?.palette;
  if (Array.isArray(p) && p.length) return p;
  return _DEFAULT_LINE_PALETTE;
}

function _multilineColour(entry, palette) {
  if (entry.channel === 'delta_time') {
    const v = entry.value ?? 0;
    if (v <= -0.10) return '#c084fc';
    if (v <   0.00) return '#22dd66';
    if (v <   1.00) return '#ffd700';
    return '#ff4444';
  }
  const pal = palette || _DEFAULT_LINE_PALETTE;
  return pal[(entry.color_idx || 0) % pal.length];
}

const GaugeMultiline = {
  render(ctx, data, w, h) {
    const theme   = GaugeBase.getTheme(data);
    const entries = (data.multi_channels || []).filter(e => e != null);
    const palette = _linePalette(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    if (entries.length === 0) {
      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle    = theme.label;
      ctx.font         = `${Math.round(w * 0.07)}px 'Segoe UI', sans-serif`;
      ctx.fillText('No channels', w * 0.5, h * 0.5);
      return;
    }

    const sc = Math.sqrt((w / 320) * (h / 120));

    // Legend width
    const maxLabel  = Math.max(...entries.map(e => (e.label || '').length));
    const legendFrac = Math.min(0.38, Math.max(0.30, 0.05 + maxLabel * 0.022));
    const legendW   = w * legendFrac;

    // Chart area (pixels)
    const cX = w * 0.05;
    const cY = h * 0.12;
    const cW = w * (0.95 - legendFrac - 0.03) - cX;
    const cH = h * 0.76;

    const gChannels = new Set(['gforce_total', 'gforce_lat', 'gforce_lon', 'g_meter']);
    const gValueTable = entries.length > 0 && entries.every(e => gChannels.has(e.channel || ''));
    const fsLeg = gValueTable
      ? Math.max(14, Math.min(Math.round(16 * sc), Math.round(h * 0.17)))
      : Math.max(8, Math.min(Math.round(8 * sc), Math.round(h * 0.09)));

    // Clip to chart area
    ctx.save();
    ctx.beginPath();
    ctx.rect(cX, cY, cW, cH);
    ctx.clip();

    // Zero line at y=0.5 (midpoint of normalised range)
    ctx.strokeStyle = 'rgba(255,255,255,0.10)';
    ctx.lineWidth   = 0.4;
    ctx.beginPath();
    ctx.moveTo(cX, cY + cH * 0.5);
    ctx.lineTo(cX + cW, cY + cH * 0.5);
    ctx.stroke();

    for (const entry of entries) {
      const vals = entry.values || [];
      const mn   = entry.min_val ?? 0;
      const mx   = entry.max_val ?? 1;
      const sym  = entry.symmetric ?? false;
      const colour = _multilineColour(entry, palette);
      const rng  = mx !== mn ? mx - mn : 1;

      if (vals.length < 2) continue;

      // Normalise each value to [0,1]
      const norm = vals.map(v => Math.max(0, Math.min(1, (v - mn) / rng)));

      function toX(i) { return cX + cW * (i / (norm.length - 1)); }
      function toY(nv) { return cY + cH * (1 - nv); }

      // Fill under trace
      const baseline = toY(sym ? 0.5 : 0);
      ctx.beginPath();
      ctx.moveTo(toX(0), baseline);
      for (let i = 0; i < norm.length; i++) ctx.lineTo(toX(i), toY(norm[i]));
      ctx.lineTo(toX(norm.length - 1), baseline);
      ctx.closePath();
      ctx.fillStyle   = colour;
      ctx.globalAlpha = 0.08;
      ctx.fill();
      ctx.globalAlpha = 1;

      // Trace line
      ctx.beginPath();
      for (let i = 0; i < norm.length; i++) {
        const x = toX(i);
        const y = toY(norm[i]);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = colour;
      ctx.lineWidth   = Math.max(1, 1.5 * sc);
      ctx.globalAlpha = 0.90;
      ctx.lineCap     = 'round';
      ctx.stroke();
      ctx.globalAlpha = 1;

      // Current value dot (rightmost point)
      const lastNorm = norm[norm.length - 1];
      ctx.beginPath();
      ctx.arc(cX + cW, toY(lastNorm), Math.max(3, 4 * sc), 0, Math.PI * 2);
      ctx.fillStyle   = colour;
      ctx.fill();
      ctx.strokeStyle = 'white';
      ctx.lineWidth   = Math.max(0.5, 0.6 * sc);
      ctx.stroke();
    }

    ctx.restore();

    // Legend (right column)
    const legendX   = w - legendW + w * 0.01;
    const nEntries  = entries.length;
    const rowH      = h * 0.80 / Math.max(nEntries, 1);
    const swatchW   = Math.round(w * 0.022);
    const swatchH   = Math.min(h * 0.05, rowH * 0.55);

    ctx.textBaseline = 'middle';
    ctx.textAlign    = 'left';

    for (let i = 0; i < entries.length; i++) {
      const entry  = entries[i];
      const colour = _multilineColour(entry, palette);
      const label  = (entry.label || '').slice(0, 6).toUpperCase();
      const unit   = entry.unit || '';
      const value  = entry.value ?? 0;

      const yCentre = h * 0.10 + rowH * (i + 0.5);

      // Colour swatch
      ctx.fillStyle = colour;
      ctx.fillRect(legendX, yCentre - swatchH / 2, swatchW, swatchH);

      // Format value
      let valStr;
      if ((entry.channel || '') === 'lap_time') {
        valStr = GaugeBase.fmtValue(value, 'lap_time');
      } else {
        const absV = Math.abs(value);
        if (absV >= 1000)     valStr = value.toFixed(0);
        else if (absV >= 100) valStr = value.toFixed(0);
        else if (absV >= 10)  valStr = value.toFixed(1);
        else                  valStr = value.toFixed(2);
      }
      if (unit) valStr += '\u202f' + unit;

      // Combined label + value
      const combined = `${label.padEnd(6)}  ${valStr}`;
      ctx.fillStyle  = colour;
      ctx.font       = `bold ${fsLeg}px 'Segoe UI', sans-serif`;
      ctx.fillText(combined, legendX + swatchW + 4, yCentre);
    }
  }
};

/* ----- splits.js ----- */
/**
 * splits.js — Sector split comparison table.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_splits.py`` / export.
 *
 * data keys: value (cur elapsed), sectors (list of {num, ref_t, cur_t, delta, done, boundary_elapsed})
 * theme keys: bg, bgEdge, label, text
 */
const GaugeSplits = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    const sectors = data.sectors || [];
    const sc = Math.sqrt((w / 160) * (h / 200));

    const fsTitle = Math.max(8, Math.min(Math.round(8 * sc), Math.round(w * 0.09)));
    const fsRow   = Math.max(8, Math.min(Math.round(9 * sc), Math.round(w * 0.09)));
    const fsHdr   = Math.max(7, Math.min(Math.round(6 * sc), Math.round(w * 0.075)));

    // Title
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle    = theme.label;
    ctx.font         = `${fsTitle}px 'Segoe UI', sans-serif`;
    ctx.fillText('SPLITS', w * 0.5, h * 0.07);

    if (sectors.length === 0) {
      ctx.fillStyle = theme.label;
      ctx.font      = `${fsRow}px 'Segoe UI', sans-serif`;
      ctx.fillText('No ref lap', w * 0.5, h * 0.5);
      return;
    }

    const n    = sectors.length;
    const yTop = h * 0.84;
    const rowH = (yTop - h * 0.10) / (n + 1);  // +1 for header

    // Column x positions (fractions of w)
    const COL_S    = w * 0.12;
    const COL_REF  = w * 0.38;
    const COL_CUR  = w * 0.62;
    const COL_DIFF = w * 0.87;

    // Header
    const yHdr = yTop - rowH * 0.45;
    ctx.fillStyle    = theme.label;
    ctx.font         = `${fsHdr}px 'Segoe UI', sans-serif`;
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';
    for (const [x, txt] of [[COL_S, 'S'], [COL_REF, 'REF'], [COL_CUR, 'CUR'], [COL_DIFF, 'DIFF']]) {
      ctx.fillText(txt, x, yHdr);
    }

    // Find next incomplete sector
    let nextIncomplete = null;
    for (let i = 0; i < sectors.length; i++) {
      if (!sectors[i].done) { nextIncomplete = i; break; }
    }

    for (let i = 0; i < sectors.length; i++) {
      const s    = sectors[i];
      const y    = yTop - (i + 1) * rowH;
      const rowY = y + rowH * 0.5;

      // Highlight current sector
      if (i === nextIncomplete) {
        ctx.fillStyle   = 'rgba(255,255,255,0.07)';
        ctx.fillRect(w * 0.05, y + 1, w * 0.90, rowH - 2);
      }

      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.font         = `${fsRow}px 'Segoe UI', sans-serif`;

      // Sector number
      ctx.fillStyle = theme.text;
      ctx.fillText(`S${s.num ?? (i + 1)}`, COL_S, rowY);

      // Ref time
      ctx.fillStyle = '#888888';
      ctx.fillText(s.ref_t != null ? s.ref_t.toFixed(3) : '\u2014', COL_REF, rowY);

      if (s.cur_t != null) {
        // Current time
        ctx.fillStyle = theme.text;
        ctx.fillText(s.cur_t.toFixed(3), COL_CUR, rowY);

        // Delta
        if (s.delta != null) {
          let dCol;
          if (Math.abs(s.delta) < 0.001) dCol = '#e8e8e8';
          else if (s.delta < 0)           dCol = '#22dd66';
          else                            dCol = '#ff4444';
          ctx.fillStyle = dCol;
          ctx.font      = `bold ${fsRow}px 'Segoe UI', sans-serif`;
          ctx.fillText((s.delta >= 0 ? '+' : '') + s.delta.toFixed(3), COL_DIFF, rowY);
          ctx.font      = `${fsRow}px 'Segoe UI', sans-serif`;
        }
      } else {
        ctx.fillStyle = '#444444';
        ctx.fillText('\u2014', COL_CUR, rowY);
        ctx.fillText('\u2014', COL_DIFF, rowY);
      }
    }
  }
};

/* ----- sector_bar.js ----- */
/**
 * sector_bar.js — Compact sector split strip.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_sector_bar.py`` / export.
 *
 * data keys: sectors (list of {num, delta, done})
 */
const GaugeSectorBar = {
  _colour(delta) {
    if (delta <= -0.10) return 'rgba(153, 38, 217, 0.95)';   // purple
    if (delta <   0.00) return 'rgba(13,  184, 71,  0.95)';  // green
    if (delta <   1.00) return 'rgba(242, 204, 13,  0.95)';  // yellow
    return                      'rgba(224, 51,  46,  0.95)';  // red
  },

  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    GaugeBase.drawBackground(ctx, w, h, theme);

    const sectors = data.sectors || [];

    if (sectors.length === 0) {
      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle    = theme.label;
      ctx.font         = `${Math.max(8, Math.round(w * 0.07))}px 'Segoe UI', sans-serif`;
      ctx.fillText('No ref lap', w * 0.5, h * 0.5);
      return;
    }

    const sc = Math.sqrt((w / 320) * (h / 60));

    const done    = sectors.filter(s => s.done && s.delta != null);
    const pending = sectors.filter(s => !s.done);

    const PAD_X  = w * 0.03;
    const PAD_Y  = h * 0.12;
    const GAP    = w * 0.008;
    const TICK_W = w * 0.012;
    const boxY1  = PAD_Y;
    const boxH   = h - 2 * PAD_Y;
    const fs     = Math.max(7, Math.min(Math.round(9 * sc), Math.round(h * 0.25)));

    const tickTotal = pending.length > 0 ? pending.length * (TICK_W + GAP) : 0;
    const boxTotal  = (w - 2 * PAD_X) - tickTotal;
    const boxW      = done.length > 0
      ? Math.max(w * 0.05, (boxTotal - GAP * (done.length - 1)) / done.length)
      : 0;

    let cursor = PAD_X;
    const r = Math.max(1, Math.round(boxH * 0.18));

    // Completed sectors
    for (const s of done) {
      const col = this._colour(s.delta);

      ctx.fillStyle = col;
      ctx.beginPath();
      GaugeBase.roundRect(ctx, cursor, boxY1, boxW, boxH, r);
      ctx.fill();

      ctx.strokeStyle = 'rgba(255,255,255,0.12)';
      ctx.lineWidth   = 0.5;
      ctx.stroke();

      // Sector label (top)
      const fsSmall = Math.max(6, Math.round(fs * 0.62));
      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle    = 'rgba(255,255,255,0.75)';
      ctx.font         = `${fsSmall}px 'Segoe UI', sans-serif`;
      ctx.fillText(`S${s.num ?? '?'}`, cursor + boxW / 2, boxY1 + boxH * 0.25);

      // Delta
      const sign   = s.delta >= 0 ? '+' : '';
      const dStr   = `${sign}${s.delta.toFixed(3)}`;
      ctx.fillStyle = 'white';
      ctx.font      = `bold ${fs}px 'Segoe UI', sans-serif`;
      ctx.fillText(dStr, cursor + boxW / 2, boxY1 + boxH * 0.68);

      cursor += boxW + GAP;
    }

    // Pending ticks
    const tickCol = 'rgba(89, 89, 128, 0.60)';
    const fsSmall = Math.max(6, Math.round(fs * 0.55));
    for (const s of pending) {
      ctx.fillStyle = tickCol;
      ctx.beginPath();
      GaugeBase.roundRect(ctx, cursor, boxY1 + boxH * 0.25, TICK_W, boxH * 0.50, 2);
      ctx.fill();

      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle    = 'rgba(170,170,204,0.60)';
      ctx.font         = `${fsSmall}px 'Segoe UI', sans-serif`;
      ctx.fillText(`S${s.num ?? '?'}`, cursor + TICK_W / 2, boxY1 + boxH * 0.50);

      cursor += TICK_W + GAP;
    }
  }
};

/* ----- dial.js ----- */
/**
 * dial.js — Circular arc gauge with needle.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_dial.py`` / export.
 *
 * Arc spans 240° clockwise from 210° to 330° (bottom-left to bottom-right).
 * Symmetric: zero at top (90°).
 *
 * data keys: value, label, unit, min_val, max_val, symmetric, channel
 */
const GaugeDial = {
  render(ctx, data, w, h) {
    const theme     = GaugeBase.getTheme(data);
    const value     = data.value     ?? 0;
    const label     = (data.label    || '').toUpperCase();
    const unit      = data.unit      || '';
    const mn        = data.min_val   ?? 0;
    const mx        = data.max_val   ?? 100;
    const symmetric = data.symmetric ?? false;
    const channel   = data.channel   || '';

    const sc = Math.sqrt((w / 160) * (h / 160));

    // Centre + radius — use the smaller dimension, leave some padding
    const dim  = Math.min(w, h);
    const cx   = w / 2;
    const cy   = h / 2;
    const R    = dim * 0.5 * 0.98;   // fills most of the cell

    // Background circle
    ctx.beginPath();
    ctx.arc(cx, cy, R * 1.00, 0, Math.PI * 2);
    ctx.fillStyle = theme.bg;
    ctx.fill();
    ctx.strokeStyle = theme.bgEdge;
    ctx.lineWidth   = 1;
    ctx.stroke();

    const ARC_START_DEG = 210;     // degrees (math convention: 0=right, CCW positive)
    const ARC_SWEEP_DEG = 240;     // total sweep clockwise
    const ARC_END_DEG   = ARC_START_DEG - ARC_SWEEP_DEG;  // = -30 = 330

    // Convert display degrees (where 0=right, CCW positive in math but we want
    // clockwise in display): Canvas uses radians where 0=right, CW positive
    function toRad(deg) {
      // Canvas: 0 = right, CW positive (i.e. +y is down)
      // Math convention to Canvas: negate, then convert
      return -deg * Math.PI / 180;
    }

    const R_TRACK  = R * 0.72;
    const LW_TRACK = Math.max(4, Math.round(10 * sc));

    const rng  = mx !== mn ? mx - mn : 1;
    const frac = Math.max(0, Math.min(1, (value - mn) / rng));

    // Track arc (full, from ARC_START_DEG to ARC_END_DEG clockwise)
    // In Canvas terms: start = toRad(ARC_START_DEG), end = toRad(ARC_END_DEG),
    // anticlockwise=true (because our toRad negates, making it CW on screen)
    ctx.beginPath();
    ctx.arc(cx, cy, R_TRACK, toRad(ARC_START_DEG), toRad(ARC_END_DEG), false);
    ctx.strokeStyle = theme.track;
    ctx.lineWidth   = LW_TRACK;
    ctx.lineCap     = 'round';
    ctx.stroke();

    // Fill arc
    let fillCol, needleAngleDeg;
    if (symmetric) {
      // Zero at 90°, fill from 90° toward ARC_START or ARC_END
      const zeroAngleDeg = 90;
      needleAngleDeg = zeroAngleDeg - ARC_SWEEP_DEG * (frac - 0.5);
      fillCol = value >= 0 ? theme.fillPos : theme.fillNeg;

      if (Math.abs(frac - 0.5) > 0.001) {
        ctx.beginPath();
        ctx.arc(cx, cy, R_TRACK, toRad(zeroAngleDeg), toRad(needleAngleDeg), false);
        ctx.strokeStyle = fillCol;
        ctx.lineWidth   = LW_TRACK;
        ctx.lineCap     = 'round';
        ctx.stroke();
      }
    } else {
      needleAngleDeg = ARC_START_DEG - ARC_SWEEP_DEG * frac;
      fillCol = frac < 0.80 ? theme.fillLo : theme.fillHi;

      if (frac > 0.001) {
        ctx.beginPath();
        ctx.arc(cx, cy, R_TRACK, toRad(ARC_START_DEG), toRad(needleAngleDeg), false);
        ctx.strokeStyle = fillCol;
        ctx.lineWidth   = LW_TRACK;
        ctx.lineCap     = 'round';
        ctx.stroke();
      }
    }

    // Tick marks at 0%, 25%, 50%, 75%, 100%
    for (const tf of [0, 0.25, 0.5, 0.75, 1.0]) {
      const taDeg = ARC_START_DEG - ARC_SWEEP_DEG * tf;
      const taRad = toRad(taDeg);
      const r0    = R * 0.62;
      const r1    = R * 0.70;
      ctx.beginPath();
      ctx.moveTo(cx + r0 * Math.cos(taRad), cy + r0 * Math.sin(taRad));
      ctx.lineTo(cx + r1 * Math.cos(taRad), cy + r1 * Math.sin(taRad));
      ctx.strokeStyle = '#2a3a4a';
      ctx.lineWidth   = Math.max(0.8, sc);
      ctx.stroke();
    }

    // Needle
    const naRad   = toRad(needleAngleDeg);
    const needleR = R * 0.60;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(cx + needleR * Math.cos(naRad), cy + needleR * Math.sin(naRad));
    ctx.strokeStyle = theme.text;
    ctx.lineWidth   = Math.max(1, 1.5 * sc);
    ctx.lineCap     = 'round';
    ctx.stroke();

    // Centre dot
    ctx.beginPath();
    ctx.arc(cx, cy, Math.max(3, 5 * sc), 0, Math.PI * 2);
    ctx.fillStyle = theme.text;
    ctx.fill();

    // Value text (slightly below centre)
    const textBudget = Math.round(Math.min(w, h) * 0.35);
    const fsValue = Math.max(8, Math.min(Math.round(22 * sc), Math.round(textBudget * 0.72)));
    const fsLabel = Math.max(7, Math.min(Math.round(9 * sc), Math.round(w * 0.08)));
    const fsUnit  = Math.max(6, Math.min(Math.round(7 * sc), Math.round(w * 0.06)));

    const valStr = GaugeBase.fmtValue(value, channel);

    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';

    ctx.fillStyle  = theme.text;
    ctx.font       = `bold ${fsValue}px 'Segoe UI', sans-serif`;
    ctx.fillText(valStr, cx, cy + R * 0.15);

    ctx.fillStyle = theme.unit;
    ctx.font      = `${fsUnit}px 'Segoe UI', sans-serif`;
    ctx.fillText(unit, cx, cy + R * 0.60);

    ctx.fillStyle = theme.label;
    ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, cx, cy - R * 0.46);
  }
};

/* ----- gmeter.js ----- */
/**
 * gmeter.js — 2D G-force meter with fading trace.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_gmeter.py`` / export.
 *
 * data keys: value (gx), value_gy, history_vals (gx list), history_gy,
 *            min_val, max_val
 */
const GaugeGmeter = {
  render(ctx, data, w, h) {
    const theme  = GaugeBase.getTheme(data);
    const gxNow  = data.value     ?? 0;
    const gyNow  = data.value_gy  ?? 0;
    const gxHist = data.history_vals || [gxNow];
    const gyHist = data.history_gy   || [gyNow];
    const gRange = data.max_val  ?? 3;

    GaugeBase.drawBackground(ctx, w, h, theme);

    // Chart margins matching Python (m_side=0.14, m_top=0.08, m_bot=0.22)
    const mSide = 0.14;
    const mTop  = 0.08;
    const mBot  = 0.22;

    // Centred square chart area
    const chartW  = w * (1 - 2 * mSide);
    const chartH  = h * (1 - mBot - mTop);
    const plotDim = Math.min(chartW, chartH);
    const cx      = w * 0.5;
    const cy      = h * mBot + chartH * 0.5;

    // Scale: plotDim pixels spans 2 * gRange * 1.20 G-units
    const scale   = plotDim / (gRange * 2 * 1.20);

    function toScreen(gx, gy) {
      // gx = longitudinal (BRAKE=+, ACCEL=-), gy = lateral (R=+, L=-)
      // In matplotlib: x=gx(lat?), y=gx(lon?)
      // From Python: gx_now is longitudinal, gy_now is lateral
      // ax.plot(gx_now, gy_now) → x=lon, y=lat
      // BUT in our display: BRAKE=top, ACCEL=bottom, R=right, L=left
      // x-axis = lateral (gy), y-axis = longitudinal (gx, positive = brake = up)
      return {
        x: cx + gy * scale,
        y: cy - gx * scale,   // negate so positive gx (brake) = up
      };
    }

    // Grid circles
    ctx.save();
    for (const r of [gRange / 3, gRange * 2 / 3, gRange]) {
      ctx.beginPath();
      ctx.arc(cx, cy, r * scale, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.15)';
      ctx.lineWidth   = 0.5;
      ctx.stroke();
    }

    // Cross-hairs
    const halfSpan = gRange * 1.20 * scale;
    ctx.strokeStyle = 'rgba(255,255,255,0.20)';
    ctx.lineWidth   = 0.5;
    ctx.beginPath();
    ctx.moveTo(cx - halfSpan, cy);
    ctx.lineTo(cx + halfSpan, cy);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(cx, cy - halfSpan);
    ctx.lineTo(cx, cy + halfSpan);
    ctx.stroke();
    ctx.restore();

    // Ring labels
    const dim   = Math.min(w, h);
    const fsRing = Math.max(7, Math.round(dim * 0.050));
    ctx.fillStyle    = 'rgba(255,255,255,0.28)';
    ctx.font         = `${fsRing}px 'Segoe UI', sans-serif`;
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'bottom';
    for (const [r, lbl] of [
      [gRange / 3,     `${(gRange / 3).toFixed(0)}G`],
      [gRange * 2 / 3, `${(gRange * 2 / 3).toFixed(0)}G`],
      [gRange,         `${gRange.toFixed(0)}G`],
    ]) {
      ctx.fillText(lbl, cx, cy - r * scale - 1);
    }

    // Axis labels
    const fsAx = Math.max(8, Math.round(dim * 0.060));
    ctx.fillStyle    = theme.label;
    ctx.font         = `${fsAx}px 'Segoe UI', sans-serif`;
    ctx.textBaseline = 'bottom';
    ctx.textAlign    = 'center';
    ctx.fillText('BRAKE', cx, cy - halfSpan);
    ctx.textBaseline = 'top';
    ctx.fillText('ACCEL', cx, cy + halfSpan);
    ctx.textBaseline = 'middle';
    ctx.textAlign    = 'left';
    ctx.fillText('R', cx + halfSpan + 2, cy);
    ctx.textAlign    = 'right';
    ctx.fillText('L', cx - halfSpan - 2, cy);

    // G readout (bottom of background area) — enlarge for readability
    const fsVal = Math.max(16, Math.round(dim * 0.13));
    ctx.fillStyle    = '#ccccdd';
    ctx.font         = `${fsVal}px 'Segoe UI', sans-serif`;
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'bottom';
    const gTotal = Math.hypot(gxNow, gyNow);
    ctx.fillText(`${gTotal.toFixed(1)} G`, w * 0.5, h * 0.97);

    // History trace (fading alpha)
    const nTrace = Math.min(60, gxHist.length);
    if (nTrace >= 2) {
      const xSlice = gxHist.slice(-nTrace);
      const ySlice = gyHist.length >= nTrace
        ? gyHist.slice(-nTrace)
        : new Array(nTrace).fill(0);

      const accCol = theme.fillLo || '#4f8ef7';
      ctx.lineCap = 'round';

      for (let i = 0; i < nTrace - 1; i++) {
        const alpha = 0.05 + 0.45 * (i / (nTrace - 1));
        const p0    = toScreen(xSlice[i],     ySlice[i]);
        const p1    = toScreen(xSlice[i + 1], ySlice[i + 1]);
        ctx.beginPath();
        ctx.moveTo(p0.x, p0.y);
        ctx.lineTo(p1.x, p1.y);
        ctx.strokeStyle = accCol;
        ctx.lineWidth   = Math.max(0.8, dim * 0.006);
        ctx.globalAlpha = alpha;
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }

    // Current dot
    const gMag   = Math.min(Math.hypot(gxNow, gyNow) / gRange, 1.0);
    const dotCol = gMag > 0.80 ? theme.fillHi : (theme.fillLo || '#4f8ef7');
    const dotR   = Math.max(5, Math.round(dim * 0.045));
    const pos    = toScreen(gxNow, gyNow);

    ctx.beginPath();
    ctx.arc(pos.x, pos.y, dotR, 0, Math.PI * 2);
    ctx.fillStyle   = dotCol;
    ctx.globalAlpha = 1;
    ctx.fill();
    ctx.strokeStyle = 'white';
    ctx.lineWidth   = Math.max(0.8, dim * 0.005);
    ctx.stroke();
  }
};

/* ----- lean.js ----- */
/**
 * lean.js — Motorcycle lean angle visualisation.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/gauge_lean.py`` / export.
 *
 * data keys: value (degrees, positive = right), label, unit, min_val, max_val
 */
const GaugeLean = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    const value  = Math.max(-90, Math.min(90, data.value ?? 0));
    const label  = (data.label || 'Lean').toUpperCase();
    const unit   = data.unit || '°';

    const sc  = Math.sqrt((w / 140) * (h / 180));
    const dim = Math.min(w, h);

    // Background circle (same as matplotlib: Circle with radius=0.98 of axis)
    const cx = w * 0.5;
    const cy = h * 0.5;
    const R  = Math.min(w, h) * 0.5 * 0.96;

    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.fillStyle = theme.bg;
    ctx.fill();
    ctx.strokeStyle = theme.bgEdge;
    ctx.lineWidth   = 1;
    ctx.stroke();

    // Lean colour
    const absLean = Math.abs(value);
    let leanCol;
    if (absLean < 20)       leanCol = theme.leanSafe;
    else if (absLean < 40)  leanCol = theme.leanWarn;
    else                    leanCol = theme.leanDanger;

    // Ground line (fixed at bottom of circle)
    const groundY = cy + R * 0.72;
    ctx.save();
    ctx.strokeStyle = theme.ground || '#2a3a4a';
    ctx.lineWidth   = Math.max(0.8, 1.2 * sc);
    ctx.beginPath();
    ctx.moveTo(cx - R * 0.85, groundY);
    ctx.lineTo(cx + R * 0.85, groundY);
    ctx.stroke();

    // Rotate canvas for bike silhouette
    const leanRad = value * Math.PI / 180;  // positive=right lean (normalized in data loaders)

    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(leanRad);

    // ── Bike body (vertical bar from -0.30 to +0.28 in normalised coords)
    const bScale = R * 0.85;  // convert normalised [-1,1] to pixels

    ctx.strokeStyle = theme.bike_body || 'white';
    ctx.lineWidth   = Math.max(2.5, 4.0 * sc);
    ctx.lineCap     = 'round';
    ctx.beginPath();
    ctx.moveTo(-0.04 * bScale, -(-0.30) * bScale);   // flip y: matplotlib y-up, canvas y-down
    ctx.lineTo(-0.04 * bScale, -(0.28) * bScale);
    ctx.stroke();

    // ── Wheels (normalised positions from Python code)
    const bikePartsCol = theme.bike_parts || '#aabbcc';

    for (const [nx, ny, nr] of [
      [0.18,  -0.38, 0.20 * sc * 0.6],
      [-0.22, -0.30, 0.19 * sc * 0.6],
    ]) {
      ctx.beginPath();
      ctx.arc(nx * bScale, -ny * bScale, nr * bScale, 0, Math.PI * 2);
      ctx.strokeStyle = bikePartsCol;
      ctx.lineWidth   = Math.max(1.5, 2.5 * sc);
      ctx.stroke();
    }

    // ── Front fork
    ctx.strokeStyle = bikePartsCol;
    ctx.lineWidth   = Math.max(1.5, 2.5 * sc);
    ctx.beginPath();
    ctx.moveTo(-0.06 * bScale, -(0.22) * bScale);
    ctx.lineTo(-0.22 * bScale, -(-0.30) * bScale);
    ctx.stroke();

    // ── Rider body + head
    const riderBodyCol = theme.rider_body || '#667799';
    const riderHeadCol = theme.rider_head || '#8899aa';

    ctx.beginPath();
    ctx.arc(0.0 * bScale, -(0.26) * bScale, 0.10 * sc * 0.7 * bScale, 0, Math.PI * 2);
    ctx.fillStyle   = riderBodyCol;
    ctx.globalAlpha = 0.90;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0.0 * bScale, -(0.50) * bScale, 0.07 * sc * 0.7 * bScale, 0, Math.PI * 2);
    ctx.fillStyle = riderHeadCol;
    ctx.fill();

    ctx.globalAlpha = 1;
    ctx.restore();  // undo rotation

    // ── Value text (rotated canvas is restored now)
    const fsVal   = Math.max(10, Math.min(Math.round(24 * sc), Math.round(w * 0.18)));
    const fsLabel = Math.max(7,  Math.min(Math.round(8  * sc), Math.round(w * 0.07)));

    const direction = value > 0 ? 'R' : (value < 0 ? 'L' : '');
    const valStr    = `${direction}${absLean.toFixed(1)}${unit}`;

    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle    = leanCol;
    ctx.font         = `bold ${fsVal}px 'Segoe UI', sans-serif`;
    ctx.fillText(valStr, cx, cy + R * 0.82);

    ctx.fillStyle = theme.label;
    ctx.font      = `${fsLabel}px 'Segoe UI', sans-serif`;
    ctx.fillText(label, cx, cy - R * 0.85);

    ctx.restore();
  }
};

/* ----- map.js ----- */
/**
 * map.js — GPS circuit map gauge.
 *
 * Editor Canvas preview; ``data`` keys match ``styles/map_*.py`` / export.
 *
 * data keys: lats (array), lons (array), cur_idx (int)
 * theme keys: map_bg_rgba, map_track_outer, map_track_inner, map_dot, map_start
 */

/**
 * Smooth polyline using midpoint quadratic bezier (Chaikin-style).
 * xs/ys are pre-projected screen coordinate arrays.
 * closed=true joins the last point back to the first seamlessly.
 */
function _strokeSmooth(ctx, xs, ys, closed) {
  const n = Math.min(xs.length, ys.length);
  if (n < 2) return;
  ctx.beginPath();
  if (closed && n > 2) {
    ctx.moveTo((xs[n - 1] + xs[0]) / 2, (ys[n - 1] + ys[0]) / 2);
    for (let i = 0; i < n - 1; i++) {
      ctx.quadraticCurveTo(xs[i], ys[i], (xs[i] + xs[i + 1]) / 2, (ys[i] + ys[i + 1]) / 2);
    }
    ctx.quadraticCurveTo(xs[n - 1], ys[n - 1], (xs[n - 1] + xs[0]) / 2, (ys[n - 1] + ys[0]) / 2);
    ctx.closePath();
  } else {
    ctx.moveTo(xs[0], ys[0]);
    for (let i = 1; i < n - 1; i++) {
      ctx.quadraticCurveTo(xs[i], ys[i], (xs[i] + xs[i + 1]) / 2, (ys[i] + ys[i + 1]) / 2);
    }
    ctx.lineTo(xs[n - 1], ys[n - 1]);
  }
}

function _transformPoint(x, y, cx, cy, rotateDeg, mirrorX, mirrorY) {
  let dx = x - cx;
  let dy = y - cy;
  if (mirrorX) dx = -dx;
  if (mirrorY) dy = -dy;
  const rad = (rotateDeg || 0) * Math.PI / 180;
  const cr = Math.cos(rad);
  const sr = Math.sin(rad);
  return {
    x: cx + (dx * cr - dy * sr),
    y: cy + (dx * sr + dy * cr),
  };
}

const GaugeMap = {
  render(ctx, data, w, h) {
    const theme = GaugeBase.getTheme(data);

    const lats     = data.lats   || [];
    const lons     = data.lons   || [];
    const curIdx   = data.cur_idx ?? 0;
    const dotLat   = Number(data.dot_lat);
    const dotLon   = Number(data.dot_lon);
    const useGpsDot = Number.isFinite(dotLat) && Number.isFinite(dotLon);
    const osmLats  = data.track_map_lats  || [];
    const osmLons  = data.track_map_lons  || [];
    const osmAreas = data.track_map_areas || [];
    const rotateDeg = Number(data.map_rotate_deg || 0);
    const mirrorX = data.map_mirror_x === true;
    const mirrorY = data.map_mirror_y === true;

    if (lats.length < 2 || lons.length < 2) {
      // Background
      ctx.fillStyle = theme.map_bg_rgba || 'rgba(0,0,0,0.65)';
      ctx.beginPath();
      GaugeBase.roundRect(ctx, 2, 2, w - 4, h - 4, Math.max(4, Math.round(Math.min(w, h) * 0.04)));
      ctx.fill();
      ctx.fillStyle    = theme.label || '#4e6578';
      ctx.font         = `${Math.round(w * 0.08)}px 'Segoe UI', sans-serif`;
      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('No GPS', w * 0.5, h * 0.5);
      return;
    }

    // ── Cache base layer (background + track polyline + OSM + start marker) ──
    // This prevents full-track redraw on every seek/jump; only the red dot changes.
    if (!GaugeMap._cache) {
      GaugeMap._cache = { arrIds: new WeakMap(), nextArrId: 1, circuit: new Map() };
    }
    const _c = GaugeMap._cache;
    const _arrId = (arr) => {
      if (!arr || typeof arr !== 'object') return 0;
      const got = _c.arrIds.get(arr);
      if (got) return got;
      const id = _c.nextArrId++;
      _c.arrIds.set(arr, id);
      return id;
    };
    const n = Math.min(lats.length, lons.length);
    const key = [
      w, h,
      rotateDeg, mirrorX ? 1 : 0, mirrorY ? 1 : 0,
      _arrId(lats), _arrId(lons),
      _arrId(osmLats), _arrId(osmLons),
      // areas array identity is enough; contents don't change during a session
      _arrId(osmAreas),
      n,
      // Theme tokens that affect the base layer
      theme.map_bg_rgba || '',
      theme.map_track_outer || '',
      theme.map_track_inner || '',
      theme.map_start || '',
    ].join('|');

    let base = _c.circuit.get(key);
    if (!base) {
      const off = document.createElement('canvas');
      off.width = Math.max(1, w);
      off.height = Math.max(1, h);
      const octx = off.getContext('2d');
      if (octx) {
        // Background
        octx.fillStyle = theme.map_bg_rgba || 'rgba(0,0,0,0.65)';
        octx.beginPath();
        GaugeBase.roundRect(octx, 2, 2, w - 4, h - 4, Math.max(4, Math.round(Math.min(w, h) * 0.04)));
        octx.fill();

        // Compute bounding box from GPS trace + OSM geometry combined
        const pad     = 0.10;
        const allLats = osmLats.length ? [...lats, ...osmLats] : lats;
        const allLons = osmLons.length ? [...lons, ...osmLons] : lons;
        const minLat  = Math.min(...allLats);
        const maxLat  = Math.max(...allLats);
        const minLon  = Math.min(...allLons);
        const maxLon  = Math.max(...allLons);
        const spanLat = maxLat - minLat || 1e-6;
        const spanLon = maxLon - minLon || 1e-6;

        // Scale preserving aspect ratio
        const availW = w * (1 - 2 * pad);
        const availH = h * (1 - 2 * pad);
        const scaleX = availW / spanLon;
        const scaleY = availH / spanLat;
        const scale  = Math.min(scaleX, scaleY);
        const offX   = w * pad + (availW - spanLon * scale) / 2;
        const offY   = h * pad + (availH - spanLat * scale) / 2;
        const tcx = w * 0.5;
        const tcy = h * 0.5;

        function toScreen(lat, lon) {
          const raw = {
            x: offX + (lon - minLon) * scale,
            y: h - offY - (lat - minLat) * scale,  // flip y (north up)
          };
          return _transformPoint(raw.x, raw.y, tcx, tcy, rotateDeg, mirrorX, mirrorY);
        }

        // Pre-project screen coordinates once per dataset
        const osmXs = [], osmYs = [];
        if (osmLats.length >= 2 && osmLons.length >= 2) {
          const on = Math.min(osmLats.length, osmLons.length);
          for (let i = 0; i < on; i++) {
            const p = toScreen(osmLats[i], osmLons[i]);
            osmXs.push(p.x); osmYs.push(p.y);
          }
        }

        const gpsXs = [], gpsYs = [];
        for (let i = 0; i < n; i++) {
          const p = toScreen(lats[i], lons[i]);
          gpsXs.push(p.x); gpsYs.push(p.y);
        }

        // OSM area polygons — filled track surface, drawn first (lowest layer)
        if (osmAreas.length) {
          octx.fillStyle = 'rgba(74,85,104,0.55)';
          for (const area of osmAreas) {
            const aLats = area.lats || [];
            const aLons = area.lons || [];
            const an = Math.min(aLats.length, aLons.length);
            if (an < 3) continue;
            octx.beginPath();
            for (let i = 0; i < an; i++) {
              const p = toScreen(aLats[i], aLons[i]);
              if (i === 0) octx.moveTo(p.x, p.y); else octx.lineTo(p.x, p.y);
            }
            octx.closePath();
            octx.fill();
          }
        }

        // OSM road background — smoothed, drawn below GPS trace
        if (osmXs.length >= 2) {
          octx.lineCap  = 'round';
          octx.lineJoin = 'round';
          _strokeSmooth(octx, osmXs, osmYs, false);
          octx.strokeStyle = '#4a5568';
          octx.lineWidth   = Math.max(6, w * 0.045);
          octx.stroke();

          _strokeSmooth(octx, osmXs, osmYs, false);
          octx.strokeStyle = '#2d3748';
          octx.lineWidth   = Math.max(4, w * 0.028);
          octx.stroke();
        }

        // Full track outline (outer) — smoothed closed circuit
        octx.lineCap  = 'round';
        octx.lineJoin = 'round';
        _strokeSmooth(octx, gpsXs, gpsYs, true);
        octx.strokeStyle = theme.map_track_outer || '#1a2a3a';
        octx.lineWidth   = Math.max(4, w * 0.03);
        octx.stroke();

        // Full track inner
        _strokeSmooth(octx, gpsXs, gpsYs, true);
        octx.strokeStyle = theme.map_track_inner || '#2255aa';
        octx.lineWidth   = Math.max(2, w * 0.015);
        octx.stroke();

        // Start marker
        const pStart = toScreen(lats[0], lons[0]);
        octx.beginPath();
        octx.arc(pStart.x, pStart.y, Math.max(3, w * 0.02), 0, Math.PI * 2);
        octx.fillStyle = theme.map_start || '#00ff88';
        octx.fill();

        // Store dot projection helper for this base (avoid recomputing bbox math)
        base = { canvas: off, toScreen, n };
        _c.circuit.set(key, base);
      }
    }

    // Paint base
    if (base?.canvas) ctx.drawImage(base.canvas, 0, 0);

    // Current position dot (prefer smooth GPS from telemetry over polyline vertex snap)
    const idx   = Math.max(0, Math.min(curIdx, n - 1));
    const toScreen = base?.toScreen;
    const pDot  = toScreen
      ? (useGpsDot ? toScreen(dotLat, dotLon) : toScreen(lats[idx], lons[idx]))
      : { x: w * 0.5, y: h * 0.5 };
    const dotR  = Math.max(4, w * 0.025);

    ctx.beginPath();
    ctx.arc(pDot.x, pDot.y, dotR, 0, Math.PI * 2);
    ctx.fillStyle = theme.map_dot || '#ff2222';
    ctx.fill();
    ctx.strokeStyle = 'white';
    ctx.lineWidth   = Math.max(1, w * 0.006);
    ctx.stroke();
  },

  /**
   * Zoomed map: centred on the current GPS position, configurable radius,
   * optional reference-lap trace rendered in purple.
   */
  renderZoomed(ctx, data, w, h) {
    const theme      = GaugeBase.getTheme(data);
    const lats       = data.lats   || [];
    const lons       = data.lons   || [];
    const curIdx     = data.cur_idx ?? 0;
    const dotLatZ    = Number(data.dot_lat);
    const dotLonZ    = Number(data.dot_lon);
    const useGpsDotZ = Number.isFinite(dotLatZ) && Number.isFinite(dotLonZ);
    const radius     = Math.max(10, data.zoom_radius_m ?? 150);
    const showRef    = data.show_ref !== false;
    const refLats    = data.ref_lats || [];
    const refLons    = data.ref_lons || [];
    const refCurIdx  = data.ref_cur_idx ?? 0;
    const osmLats    = data.track_map_lats  || [];
    const osmLons    = data.track_map_lons  || [];
    const osmAreas   = data.track_map_areas || [];
    const rotateDeg  = Number(data.map_rotate_deg || 0);
    const mirrorX    = data.map_mirror_x === true;
    const mirrorY    = data.map_mirror_y === true;

    if (lats.length < 2) {
      ctx.fillStyle    = theme.label || '#4e6578';
      ctx.font         = `${Math.round(w * 0.08)}px 'Segoe UI', sans-serif`;
      ctx.textAlign    = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('No GPS', w * 0.5, h * 0.5);
      return;
    }

    const safeIdx   = Math.max(0, Math.min(curIdx, lats.length - 1));
    const centerLat = useGpsDotZ ? dotLatZ : lats[safeIdx];
    const centerLon = useGpsDotZ ? dotLonZ : lons[safeIdx];

    // GPS → local metres
    const LAT_M = 111000;
    const LON_M = 111000 * Math.cos(centerLat * Math.PI / 180);

    // canvas: centre maps to current position; radius maps to half the smaller dimension
    const pad   = 0.08;
    const avail = Math.min(w, h) * (1 - 2 * pad);
    const scale = avail * 0.5 / radius;
    const cx    = w / 2;
    const cy    = h / 2;

    function toScreen(lat, lon) {
      const raw = {
        x: cx + (lon - centerLon) * LON_M * scale,
        y: cy - (lat - centerLat) * LAT_M * scale,
      };
      return _transformPoint(raw.x, raw.y, cx, cy, rotateDeg, mirrorX, mirrorY);
    }

    // Clip to gauge bounds
    ctx.save();
    ctx.beginPath();
    GaugeBase.roundRect(ctx, 4, 4, w - 8, h - 8, Math.max(3, Math.round(Math.min(w, h) * 0.03)));
    ctx.clip();

    const n = Math.min(lats.length, lons.length);

    // Pre-project screen coordinates once per dataset
    const osmXsZ = [], osmYsZ = [];
    if (osmLats.length >= 2 && osmLons.length >= 2) {
      const on = Math.min(osmLats.length, osmLons.length);
      for (let i = 0; i < on; i++) {
        const p = toScreen(osmLats[i], osmLons[i]);
        osmXsZ.push(p.x); osmYsZ.push(p.y);
      }
    }

    const gpsXsZ = [], gpsYsZ = [];
    for (let i = 0; i < n; i++) {
      const p = toScreen(lats[i], lons[i]);
      gpsXsZ.push(p.x); gpsYsZ.push(p.y);
    }

    // OSM area polygons — filled track surface, drawn first (lowest layer)
    if (osmAreas.length) {
      ctx.fillStyle = 'rgba(74,85,104,0.55)';
      for (const area of osmAreas) {
        const aLats = area.lats || [];
        const aLons = area.lons || [];
        const an = Math.min(aLats.length, aLons.length);
        if (an < 3) continue;
        ctx.beginPath();
        for (let i = 0; i < an; i++) {
          const p = toScreen(aLats[i], aLons[i]);
          if (i === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
        }
        ctx.closePath();
        ctx.fill();
      }
    }

    // OSM road background — smoothed
    if (osmXsZ.length >= 2) {
      ctx.lineCap  = 'round';
      ctx.lineJoin = 'round';
      _strokeSmooth(ctx, osmXsZ, osmYsZ, false);
      ctx.strokeStyle = '#4a5568';
      ctx.lineWidth   = Math.max(6, w * 0.045);
      ctx.stroke();

      _strokeSmooth(ctx, osmXsZ, osmYsZ, false);
      ctx.strokeStyle = '#2d3748';
      ctx.lineWidth   = Math.max(4, w * 0.028);
      ctx.stroke();
    }

    // Full track — outer, smoothed closed circuit
    ctx.lineCap  = 'round';
    ctx.lineJoin = 'round';
    _strokeSmooth(ctx, gpsXsZ, gpsYsZ, true);
    ctx.strokeStyle = theme.map_track_outer || '#1a2a3a';
    ctx.lineWidth   = Math.max(4, w * 0.03);
    ctx.stroke();

    // Full track — inner
    _strokeSmooth(ctx, gpsXsZ, gpsYsZ, true);
    ctx.strokeStyle = theme.map_track_inner || '#2255aa';
    ctx.lineWidth   = Math.max(2, w * 0.015);
    ctx.stroke();

    // Reference lap trace (purple) — smoothed
    if (showRef && refLats.length >= 2 && refLons.length >= 2) {
      const refXs = [], refYs = [];
      const rn = Math.min(refLats.length, refLons.length);
      for (let i = 0; i < rn; i++) {
        const p = toScreen(refLats[i], refLons[i]);
        refXs.push(p.x); refYs.push(p.y);
      }
      _strokeSmooth(ctx, refXs, refYs, true);
      ctx.strokeStyle = '#cc44ff';
      ctx.lineWidth   = Math.max(2, w * 0.013);
      ctx.stroke();
    }

    // Start marker
    const pStart = toScreen(lats[0], lons[0]);
    ctx.beginPath();
    ctx.arc(pStart.x, pStart.y, Math.max(3, w * 0.02), 0, Math.PI * 2);
    ctx.fillStyle = theme.map_start || '#00ff88';
    ctx.fill();

    // Reference position dot (purple, slightly smaller than main dot)
    if (showRef && refLats.length >= 2) {
      const safeRefIdx = Math.max(0, Math.min(refCurIdx, refLats.length - 1));
      const pRef = toScreen(refLats[safeRefIdx], refLons[safeRefIdx]);
      const refDotR = Math.max(3, w * 0.022);
      ctx.beginPath();
      ctx.arc(pRef.x, pRef.y, refDotR, 0, Math.PI * 2);
      ctx.fillStyle = '#cc44ff';
      ctx.fill();
      ctx.strokeStyle = 'white';
      ctx.lineWidth   = Math.max(1, w * 0.006);
      ctx.stroke();
    }

    // Current position dot (telemetry GPS when provided)
    const pDot = useGpsDotZ ? toScreen(dotLatZ, dotLonZ) : toScreen(lats[safeIdx], lons[safeIdx]);
    const dotR = Math.max(4, w * 0.028);
    ctx.beginPath();
    ctx.arc(pDot.x, pDot.y, dotR, 0, Math.PI * 2);
    ctx.fillStyle = theme.map_dot || '#ff2222';
    ctx.fill();
    ctx.strokeStyle = 'white';
    ctx.lineWidth   = Math.max(1, w * 0.007);
    ctx.stroke();

    ctx.restore();

    // Feather/fade edges using destination-out with a radial gradient
    const featherR = Math.min(w, h) * 0.5;
    const grad = ctx.createRadialGradient(cx, cy, featherR * 0.65, cx, cy, featherR);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,1)');
    ctx.save();
    ctx.globalCompositeOperation = 'destination-out';
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  },
};

/* ----- image.js ----- */
/**
 * image.js — Image overlay gauge (logo / watermark).
 *
 * data keys:
 *   image_url   — absolute HTTP URL (from file server) or empty string
 *   image_path  — Windows path (for display only)
 *   opacity     — 0.0–1.0 (default 1.0)
 *   fit         — 'contain' | 'cover' | 'stretch' (default 'contain')
 */

const GaugeImage = (() => {
  // Cache: url → HTMLImageElement (null = failed)
  const _cache = {};

  function _placeholder(ctx, w, h) {
    const cell = Math.max(4, Math.round(Math.min(w, h) / 8));
    for (let y = 0; y < h; y += cell) {
      for (let x = 0; x < w; x += cell) {
        ctx.fillStyle = ((Math.floor(x / cell) + Math.floor(y / cell)) % 2 === 0)
          ? '#2a2a2a' : '#181818';
        ctx.fillRect(x, y, Math.min(cell, w - x), Math.min(cell, h - y));
      }
    }
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    const fs = Math.max(8, Math.round(Math.min(w, h) * 0.14));
    ctx.font = `${fs}px sans-serif`;
    ctx.textAlign    = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('IMAGE', w / 2, h / 2);
  }

  function _drawImage(ctx, img, w, h, fit, opacity) {
    const iw = img.naturalWidth;
    const ih = img.naturalHeight;
    let dx = 0, dy = 0, dw = w, dh = h;

    if (fit === 'contain') {
      const scale = Math.min(w / iw, h / ih);
      dw = iw * scale;
      dh = ih * scale;
      dx = (w - dw) / 2;
      dy = (h - dh) / 2;
    } else if (fit === 'cover') {
      const scale = Math.max(w / iw, h / ih);
      dw = iw * scale;
      dh = ih * scale;
      dx = (w - dw) / 2;
      dy = (h - dh) / 2;
    }
    // 'stretch' → use full dx/dy/dw/dh as-is

    ctx.save();
    ctx.globalAlpha = Math.max(0, Math.min(1, opacity ?? 1.0));
    ctx.drawImage(img, dx, dy, dw, dh);
    ctx.restore();
  }

  return {
    render(ctx, data, w, h) {
      const url     = data.image_url  || '';
      const opacity = data.opacity    ?? 1.0;
      const fit     = data.fit        || 'contain';

      if (!url) {
        _placeholder(ctx, w, h);
        return;
      }

      const cached = _cache[url];

      if (cached === null) {
        // Previously failed — show placeholder
        _placeholder(ctx, w, h);
        return;
      }

      if (cached && cached.complete && cached.naturalWidth > 0) {
        _drawImage(ctx, cached, w, h, fit, opacity);
        return;
      }

      if (!cached) {
        // Start loading
        const img = new Image();
        _cache[url] = img;           // mark as pending (truthy)
        img.onload  = () => { /* next render will pick it up */ };
        img.onerror = () => { _cache[url] = null; };
        img.src = url;
      }

      // Still loading — show placeholder this frame
      _placeholder(ctx, w, h);
    },

    clearCache(url) {
      if (url) delete _cache[url];
      else Object.keys(_cache).forEach(k => delete _cache[k]);
    },
  };
})();

function _normalizeData(d) {
  const o = Object.assign({}, d);
  delete o._theme;
  if (!o.theme) o.theme = 'Dark';
  return o;
}

const GAUGE_STYLE_RENDERERS = {
  'Numeric':    (ctx, d, w, h) => GaugeNumeric.render(ctx, d, w, h),
  'Info':       (ctx, d, w, h) => GaugeInfo.render(ctx, d, w, h),
  'Scoreboard': (ctx, d, w, h) => GaugeScoreboard.render(ctx, d, w, h),
  'Bar':        (ctx, d, w, h) => GaugeBar.render(ctx, d, w, h),
  'Line':       (ctx, d, w, h) => GaugeLine.render(ctx, d, w, h),
  'Delta':      (ctx, d, w, h) => GaugeDelta.render(ctx, d, w, h),
  'Delta Bar':  (ctx, d, w, h) => GaugeDeltaBar.render(ctx, d, w, h),
  'Compare':    (ctx, d, w, h) => GaugeCompare.render(ctx, d, w, h),
  'Multi-Line': (ctx, d, w, h) => GaugeMultiline.render(ctx, d, w, h),
  'Splits':     (ctx, d, w, h) => GaugeSplits.render(ctx, d, w, h),
  'Sector Bar': (ctx, d, w, h) => GaugeSectorBar.render(ctx, d, w, h),
  'Dial':       (ctx, d, w, h) => GaugeDial.render(ctx, d, w, h),
  'G-Meter':    (ctx, d, w, h) => GaugeGmeter.render(ctx, d, w, h),
  'Lean':       (ctx, d, w, h) => GaugeLean.render(ctx, d, w, h),
};

function _imgPlaceholder(ctx, w, h) {
  const cell = Math.max(4, Math.round(Math.min(w, h) / 8));
  for (let y = 0; y < h; y += cell) {
    for (let x = 0; x < w; x += cell) {
      ctx.fillStyle = ((Math.floor(x / cell) + Math.floor(y / cell)) % 2 === 0) ? '#2a2a2a' : '#181818';
      ctx.fillRect(x, y, Math.min(cell, w - x), Math.min(cell, h - y));
    }
  }
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  const fs = Math.max(8, Math.round(Math.min(w, h) * 0.14));
  ctx.font = `${fs}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('IMAGE', w / 2, h / 2);
}

async function _renderImageLayer(ctx, w, h, d0) {
  const d = _normalizeData(d0);
  const p = (d.image_path || '').trim();
  if (!p) { _imgPlaceholder(ctx, w, h); return; }
  try {
    const img = await loadImage(p);
    const opacity = d.opacity != null ? Math.max(0, Math.min(1, Number(d.opacity))) : 1.0;
    const fit = d.fit || 'contain';
    const iw = img.width;
    const ih = img.height;
    let dx = 0, dy = 0, dw = w, dh = h;
    if (fit === 'contain') {
      const scale = Math.min(w / iw, h / ih);
      dw = iw * scale; dh = ih * scale;
      dx = (w - dw) / 2; dy = (h - dh) / 2;
    } else if (fit === 'cover') {
      const scale = Math.max(w / iw, h / ih);
      dw = iw * scale; dh = ih * scale;
      dx = (w - dw) / 2; dy = (h - dh) / 2;
    }
    ctx.save();
    ctx.globalAlpha = opacity;
    ctx.drawImage(img, dx, dy, dw, dh);
    ctx.restore();
  } catch (e) {
    _imgPlaceholder(ctx, w, h);
  }
}

async function renderOverlayFrame(plan) {
  const vw = plan.vw | 0;
  const vh = plan.vh | 0;
  const layers = plan.layers || [];
  const out = createCanvas(Math.max(1, vw), Math.max(1, vh));
  const g = out.getContext('2d');
  g.clearRect(0, 0, vw, vh);

  for (const L of layers) {
    const { el, style, x, y, w, h, data } = L;
    const ww = Math.max(1, w | 0);
    const hh = Math.max(1, h | 0);
    const dc = createCanvas(ww, hh);
    const dctx = dc.getContext('2d');
    const d = _normalizeData(data || {});

    if (style === 'Image') {
      await _renderImageLayer(dctx, ww, hh, d);
    } else if (el === 'map') {
      if (style === 'Zoomed') GaugeMap.renderZoomed(dctx, d, ww, hh);
      else GaugeMap.render(dctx, d, ww, hh);
    } else {
      const fn = GAUGE_STYLE_RENDERERS[style];
      if (fn) fn(dctx, d, ww, hh);
    }
    g.drawImage(dc, x | 0, y | 0);
  }
  return out;
}

module.exports = { renderOverlayFrame, createCanvas };
